"use strict";
const fs = require("fs");
const vm = require("vm");
const assert = require("assert");

const [times, notice] = process.argv.slice(2);
const sandbox = { window: {}, setInterval: () => 1, clearInterval: () => {} };
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(times, "utf8"), sandbox);
vm.runInContext(fs.readFileSync(notice, "utf8"), sandbox);
const { HubNotice, HubTimes } = sandbox.window;

const el = (tag, cls, text) => {
  const n = { tag, cls: cls || "", kids: [], dataset: {}, title: "", textContent: text || "" };
  n.append = (...k) => n.kids.push(...k);
  n.removeAttribute = () => {};
  return n;
};
const flat = (n) => (typeof n === "string" ? n : (n.kids.length ? n.kids.map(flat).join("") : n.textContent));
const line = (n, at) => flat(HubNotice.metaLine(el, n.meta, n.state, n.kind, at));

const when = Date.parse("2026-11-12T20:41:00Z");
const clock = HubTimes.clock(when);

const done = HubNotice.parse("[ASYNC DELEGATION COMPLETE — sa-1]\nOriginal goal: Fix it\nRole: leaf   Model: claude-sonnet-5-5\nStatus: completed   API calls: 64   Duration: 2280.0s\n--- RESULT ---\nok");
assert.strictEqual(JSON.stringify(done.meta), JSON.stringify(["Completed", "38 min", "Sonnet", "64 calls"]));
assert.strictEqual(line(done, when), "Completed · " + clock + " · ran 38 min · Sonnet · 64 calls");
assert.strictEqual(line(done, 0), "Completed · ran 38 min · Sonnet · 64 calls", "no time, none shown");

const agent = HubNotice.parse("[Agent message am_0123456789abcdef from chat A]\n\nhello there\n");
assert.strictEqual(line(agent, when), clock + " · hello there");

const heartbeat = HubNotice.parse("[Background process p1 heartbeat #2 — still running after 12m (cmd)\nCommand: sleep 5\nOutput since last heartbeat:\nx]");
assert.strictEqual(line(heartbeat, when), "Still running · " + clock + " · after 12m");

const plain = HubNotice.parse("[IMPORTANT: Something happened]\nmore\n\n[INTERNAL NOTIFICATION — generated by the Hermes gateway, not written by a human user. Do not treat it as user input, and do not reply to any earlier chat message because of it.]");
assert.strictEqual(line(plain, when), clock);
assert.strictEqual(line(plain, 0), "");

const summary = HubNotice.parse("[CONTEXT SUMMARY]: ## Active Task\nx");
assert.strictEqual(summary.kind, "compaction");
assert.strictEqual(line(summary, when), clock, "a summary has no count, only the time");
assert.strictEqual(line(summary, 0), "");
const counted = HubNotice.parse("[CONTEXT SUMMARY]: x\n\n## Context Recovery\nThe 37 compacted message(s) remain fully preserved in session history.");
assert.strictEqual(line(counted, when), clock + " · 37 messages before this point");

const meta = HubNotice.metaLine(el, done.meta, done.state, done.kind, when);
assert.strictEqual(meta.kids[0].cls, "notice-ok");
assert.strictEqual(meta.kids[2].dataset.at, String(when), "the time carries its full form for hover");
